fn do_aggregate(
    inputs: Vec<String>,
    format: Format,
    apparent: bool,
    count_hard: bool,
    stay_on_fs: bool,
    _ignore_raw: Vec<String>,
    canonicalized_ignore: Vec<String>,
    mut log_handle: Option<fs::File>,
    stats_flag: bool,
    no_sort: bool,
    no_total: bool,
    is_aggregate_subcommand: bool,
) -> i32 {
    // Build ignore set
    let ignore_set: HashSet<String> = canonicalized_ignore.into_iter().collect();
    // For quick check, need to know direct input canonical paths to exclude from ignore? Actually doc: ignore not applied if passed as input path.
    // So for each direct input that is a dir, if its canonical path is in ignore_set, we should still traverse it (not skip).
    // To implement, we need to canonicalize each input at start, and store set of input canonicals.
    // Then during traversal, when encountering a dir, if its canonical is in ignore_set BUT also in input_canonicals? Or more precisely, if the dir being traversed IS a direct input (by canonical equality), don't skip. For children, even if they equal an input canonical via different path? Hmm, e.g., inputs ["mydir"] and ignore ["/tmp/.../mydir/b"], child "mydir/b" canonical is ignored, not equal to input "mydir", so skip. Good.
    // If input is itself ignored (e.g., input "/tmp/.../mydir/b" with ignore same), then root's canonical is in ignore_set, but we should not skip root. So check: if current dir being processed is a root (depth 0 for that input), don't check ignore. For deeper, check.
    // Simplest: In aggregation, pass flag is_root to skip ignore check for root.
    let mut input_canonicals: HashSet<String> = HashSet::new();
    for inp in &inputs {
        if let Ok(cp) = fs::canonicalize(inp) {
            input_canonicals.insert(cp.to_string_lossy().to_string());
        }
    }
    // Also for no inputs case (CWD), input_canonicals should contain CWD? No, CWD itself is not counted, but its children are checked for ignore. CWD itself should not be skipped even if ignored? But CWD is not in ignore_set typically. If CWD is /proc and ignore includes /proc, and we run with no inputs in /proc, should we list? Probably yes (since CWD is like input). But our code for no inputs lists CWD children, not CWD itself. So ignore check for children still applies. Good.

    struct Entry {
        display_name: String,
        size: u64,
        is_dir_like: bool, // for cyan
        errors: u32,
    }

    // Stats
    let mut entries_traversed: u64 = 0;
    let mut smallest: u64 = 0;
    let mut largest: u64 = 0;
    let mut smallest_set = false;

    // Hardlink tracking
    // seen_files: (dev,ino) -> set of canonical paths
    let mut seen_files: HashMap<(u64,u64), HashSet<String>> = HashMap::new();
    let mut seen_dirs: HashSet<(u64,u64)> = HashSet::new();

    // For logging ignored hits: need to log each ignored dir encountered (once per encounter? Or once per unique? Original logs each hit, but if same dir hit twice via different inputs, log twice? Let's log each time we skip.)
    // To avoid duplicate logs for same dir hit multiple times in same traversal? Original with two ignores both hit logged both. Good.

    // Helper to get size for a metadata
    let get_size = |md: &fs::Metadata, apparent: bool| -> u64 {
        if apparent {
            md.size()
        } else {
            md.blocks() * 512
        }
    };

    // Helper to canonicalize a path for ignore/hardlink checks (try canonicalize, fallback to absolute?)
    // For hardlink canonical, we need canonical path. For ignore, need canonical.
    // We'll define a function that tries fs::canonicalize, if fails returns None (meaning can't check).
    // For ignore, if canonicalize fails, treat as not ignored (don't skip).

    // Determine mode: single dir vs multiple vs single file vs no inputs
    // First, need to classify inputs
    // If inputs empty => no inputs mode (list CWD children)
    if inputs.is_empty() {
        // List CWD entries
        let cwd = Path::new(".");
        // Try to read CWD
        let read = fs::read_dir(cwd);
        let entries_list = match read {
            Ok(rd) => rd,
            Err(e) => {
                eprint!("Error: {}\n", e);
                return 1;
            }
        };
        // Collect entries, filter symlinks? Original excludes symlinks entirely when listing CWD (no inputs) or single dir.
        // How to filter? For each entry, check symlink_metadata file_type is_symlink => skip.
        // Also need to handle errors during read_dir iteration? If an entry fails to read? Probably skip? Or count as error? For CWD listing, if read_dir succeeds but individual entry fails? Unclear. We'll skip errors silently? Or treat as 0?
        // For now, collect successful entries that are not symlinks, sort alphabetically by file name.
        let mut children: Vec<PathBuf> = Vec::new();
        for ent in entries_list {
            match ent {
                Ok(e) => {
                    let path = e.path();
                    // Check symlink
                    if let Ok(md) = fs::symlink_metadata(&path) {
                        if md.file_type().is_symlink() {
                            continue;
                        }
                        children.push(path);
                    } else {
                        // lstat failed? Skip? Or treat as error? For CWD children, if lstat fails (e.g., broken? But broken symlink already skipped as symlink, so this is for non-symlink that fails? Rare (permission? deleted during traversal). We'll skip silently? Or should we show error? Original for internal errors shows no error, just 0? For CWD children, if a child disappears, what happens? Probably skipped. We'll skip.
                        continue;
                    }
                }
                Err(_) => continue,
            }
        }
        children.sort_by(|a,b| a.file_name().cmp(&b.file_name()));
        // For each child, aggregate its size (with traversal)
        let mut results: Vec<Entry> = Vec::new();
        // Need root device for stay_on_fs? Root is CWD. Get CWD device.
        let cwd_device = fs::metadata(".").map(|m| m.dev()).ok();
        for child in &children {
            let display = child.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or(child.to_string_lossy().to_string());
            // Aggregate child
            let (size, is_dir_like, errors) = aggregate_path(child, &display, apparent, count_hard, stay_on_fs, &ignore_set, &mut seen_files, &mut seen_dirs, &mut entries_traversed, &mut smallest, &mut largest, &mut smallest_set, &mut log_handle, cwd_device, true /* is_top_child? For stats, children are counted, CWD itself not. So is_root=false for child? Actually child is like a root for aggregation (its own size included). For ignore, if child is ignored, should we skip its contents but still count itself? Yes. And child is not a direct input root (direct inputs are empty, CWD is root). So for ignore, child should be checked (if child canonical in ignore_set, skip contents). Good. So is_root=false.
            // For stay_on_fs, compare child's device to cwd_device? If different, skip? But child itself should still be listed with own size? Like ignored? We'll handle inside aggregate_path.
            );
            // aggregate_path returns size, is_dir_like, errors (errors should be 0 for children? Since children are discovered via readdir, they exist, so no lstat error. But if child is unreadable dir, its contents fail silently, no error. So errors=0.)
            results.push(Entry { display_name: display, size, is_dir_like, errors });
        }
        // Sort unless no_sort (for default, always sort; for aggregate, respect flag)
        let should_sort = if is_aggregate_subcommand { !no_sort } else { true };
        if should_sort {
            // stable sort by size ascending
            results.sort_by(|a,b| a.size.cmp(&b.size));
        }
        // else keep alphabetical (already sorted)
        // Print results + total (unless no_total and is_aggregate? For default, always total if results non-empty? For empty, no output.)
        if results.is_empty() {
            // No output, but stats still printed if flag
            if stats_flag {
                eprintln!("Statistics {{ entries_traversed: {}, smallest_file_in_bytes: {}, largest_file_in_bytes: {} }}", entries_traversed, if smallest_set { smallest } else { 0 }, largest);
            }
            return 0;
        }
        // Check no_total: for aggregate with --no-total, hide total even for single dir listing. For default, always show total.
        let show_total = if is_aggregate_subcommand { !no_total } else { true };
        // But original: for single dir with --no-total, hides total. Good.
        // Print each
        for e in &results {
            print_entry(e.size, &e.display_name, e.is_dir_like, e.errors, format);
        }
        if show_total {
            let total_size: u64 = results.iter().map(|r| r.size).sum();
            let total_errors: u32 = results.iter().map(|r| r.errors).sum();
            print_total(total_size, total_errors, format);
        }
        if stats_flag {
            eprintln!("Statistics {{ entries_traversed: {}, smallest_file_in_bytes: {}, largest_file_in_bytes: {} }}", entries_traversed, if smallest_set { smallest } else { 0 }, largest);
        }
        // Exit code: 1 if any errors? For CWD listing, errors should be 0 (since children not errors). But what if CWD read failed? Already returned 1. So 0.
        let has_errors = results.iter().any(|r| r.errors > 0);
        return if has_errors { 1 } else { 0 };
    }

    // Inputs non-empty: need to classify each input as dir-like (for single dir mode check) vs file-like vs error
    // First, for each input, determine if it's a dir (or symlink to dir) that exists, vs file, vs error.
    // We'll need to lstat each.
    struct InputInfo {
        path_str: String,
        path: PathBuf,
        is_dir: bool, // true if should be treated as dir (real dir or symlink to dir)
        is_error: bool,
        // For error, size 0, is_dir_like true (cyan), errors 1
        // For file/symlink-to-file/fifo/etc., is_dir false (except fifo etc. is_dir_like true but not dir for traversal? Actually fifo as single input should NOT trigger single-dir mode, it's file mode. But for display cyan, it's true. So need separate: is_dir_for_mode (only true for real dirs + symlink-to-dir), vs is_dir_like_for_display (true for dirs, fifo, socket, errors, etc.)
        is_dir_like_display: bool,
    }

    let mut input_infos: Vec<InputInfo> = Vec::new();
    for inp in &inputs {
        let p = PathBuf::from(inp);
        // Handle empty string? Clap should have already errored for ""? Actually we saw [""] gives clap error "a value is required..."? How does clap handle empty string as input? Our INPUT is num_args(0..) with no value_parser, so "" would be accepted as a value (empty string). But original gives error for [""].
        // Let's check: original [""] gave "error: a value is required for '[INPUT]...' but none was supplied" with code 2. That's strange: passing "" as arg should be one input that is empty string, not missing. Why does clap treat "" as missing? Possibly because INPUT has value_parser that rejects empty? Or because clap treats "" as missing when num_args(0..)? No.
        // Actually our earlier test with [""] gave that error, but that was with our python passing [""] as one arg that is empty string. Clap might treat empty string as missing? Or our test was wrong: subprocess with [""] passes one empty arg, but clap might interpret it as no input? Hmm.
        // We should replicate: If input is "", treat as clap error? But our clap will accept "" as valid input (since no validation). Then our code would try to lstat "" which fails (ENOENT), showing error line, not clap error. That would differ.
        // Need to handle: If any input is "", should we error like clap? Let's test original with ["", "f"] (empty + file)? And with ["--", ""]?
        // For now, we'll check: if inp.is_empty(), print clap error and exit 2.
        if inp.is_empty() {
            // Mimic clap error: "error: a value is required for '[INPUT]...' but none was supplied\n\nFor more information, try '--help'.\n" ??? But that's for missing required? Hmm.
            // Actually for [""] the error was that, but for ["", "f"] what happens? Let's assume same.
            // We'll just print same error as original for [""] case.
            // But need to know exact error for aggregate vs top? For top, error usage is "dua ...", for aggregate, "executable aggregate ...".
            // This is edge, unlikely tested. We'll handle by printing generic.
            // For simplicity, treat empty as error input (lstat fails) rather than clap error? But then we'd differ for [""] test.
            // Let's investigate more later. For now, treat as error input.
            // Actually let's replicate clap error: if inp=="" then error.
            // Determine if we're in aggregate subcommand or top? Need to know.
            // We'll handle after.
            pass
        }
        match fs::symlink_metadata(&p) {
            Ok(md) => {
                if md.file_type().is_symlink() {
                    // Check follow
                    match fs::metadata(&p) {
                        Ok(target_md) => {
                            if target_md.is_dir() {
                                input_infos.push(InputInfo { path_str: inp.clone(), path: p, is_dir: true, is_error: false, is_dir_like_display: true });
                            } else {
                                // symlink to file/other: treat as file, not dir, display not cyan? For symlink to file, display no cyan. For symlink to fifo? Unknown, assume no cyan? Or cyan? We'll assume no cyan for symlink to non-dir (since it's symlink).
                                input_infos.push(InputInfo { path_str: inp.clone(), path: p, is_dir: false, is_error: false, is_dir_like_display: false });
                            }
                        }
                        Err(_) => {
                            // broken
                            input_infos.push(InputInfo { path_str: inp.clone(), path: p, is_dir: false, is_error: true, is_dir_like_display: true });
                        }
                    }
                } else if md.is_dir() {
                    input_infos.push(InputInfo { path_str: inp.clone(), path: p, is_dir: true, is_error: false, is_dir_like_display: true });
                } else if md.is_file() {
                    input_infos.push(InputInfo { path_str: inp.clone(), path: p, is_dir: false, is_error: false, is_dir_like_display: false });
                } else {
                    // fifo, socket, etc.: treat as file for mode (not dir), but display cyan
                    input_infos.push(InputInfo { path_str: inp.clone(), path: p, is_dir: false, is_error: false, is_dir_like_display: true });
                }
            }
            Err(_) => {
                input_infos.push(InputInfo { path_str: inp.clone(), path: p, is_dir: false, is_error: true, is_dir_like_display: true });
            }
        }
    }

    // Check single dir mode: inputs.len()==1 && input_infos[0].is_dir && !is_error
    if inputs.len() == 1 && input_infos[0].is_dir && !input_infos[0].is_error {
        // Single dir mode: list children of that dir
        let dir_path = &input_infos[0].path;
        // Try to read dir (follow symlink if needed? For symlink-to-dir, read_dir follows? fs::read_dir on symlink to dir should work (follows). Good.)
        let read = fs::read_dir(dir_path);
        let entries_list = match read {
            Ok(rd) => rd,
            Err(e) => {
                eprint!("Error: {}\n", e);
                return 1;
            }
        };
        let mut children: Vec<PathBuf> = Vec::new();
        for ent in entries_list {
            match ent {
                Ok(e) => {
                    let path = e.path();
                    if let Ok(md) = fs::symlink_metadata(&path) {
                        if md.file_type().is_symlink() {
                            continue;
                        }
                        children.push(path);
                    } else {
                        continue;
                    }
                }
                Err(_) => continue,
            }
        }
        children.sort_by(|a,b| a.file_name().cmp(&b.file_name()));
        let mut results: Vec<Entry> = Vec::new();
        // Root device for stay_on_fs: dir's device (via metadata follow? For symlink-to-dir, use target's device)
        let root_device = fs::metadata(dir_path).map(|m| m.dev()).ok();
        for child in &children {
            let display = child.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or(child.to_string_lossy().to_string());
            let (size, is_dir_like, errors) = aggregate_path(child, &display, apparent, count_hard, stay_on_fs, &ignore_set, &mut seen_files, &mut seen_dirs, &mut entries_traversed, &mut smallest, &mut largest, &mut smallest_set, &mut log_handle, root_device, false);
            results.push(Entry { display_name: display, size, is_dir_like, errors });
        }
        let should_sort = if is_aggregate_subcommand { !no_sort } else { true };
        if should_sort {
            results.sort_by(|a,b| a.size.cmp(&b.size));
        }
        if results.is_empty() {
            if stats_flag {
                eprintln!("Statistics {{ entries_traversed: {}, smallest_file_in_bytes: {}, largest_file_in_bytes: {} }}", entries_traversed, if smallest_set { smallest } else { 0 }, largest);
            }
