fn print_entry(size: u64, name: &str, is_dir_like: bool, errors: u32, format: Format) {
    let size_str = format_size(size, format);
    // green
    print!("\x1b[32m{}\x1b[39m ", size_str);
    if is_dir_like {
        print!("\x1b[36m{}\x1b[39m", name);
    } else {
        print!("{}", name);
    }
    if errors == 1 {
        print!("  <1 IO Error>");
    } else if errors > 1 {
        print!("  <{} IO Errors>", errors);
    }
    println!();
}

fn print_total(size: u64, errors: u32, format: Format) {
    let size_str = format_size(size, format);
    print!("\x1b[32m{}\x1b[39m total", size_str);
    if errors == 1 {
        print!("  <1 IO Error>");
    } else if errors > 1 {
        print!("  <{} IO Errors>", errors);
    }
    println!();
}

// aggregate_path: compute size for a path (file or dir), updating stats and seen sets, handling ignore, stay_on_fs, hardlinks.
// Returns (size, is_dir_like, errors) - errors should be 0 for successful (since internal errors ignored), but for direct file that fails? Actually this is called for paths that already lstat succeeded (children via readdir, or direct inputs that succeeded). So no errors. But for safety, return 0.
