#[allow(clippy::too_many_arguments)]
fn aggregate_path(
    path: &Path,
    _display: &str,
    apparent: bool,
    count_hard: bool,
    stay_on_fs: bool,
    ignore_set: &HashSet<String>,
    seen_files: &mut HashMap<(u64,u64), HashSet<String>>,
    seen_dirs: &mut HashSet<(u64,u64)>,
    entries_traversed: &mut u64,
    smallest: &mut u64,
    largest: &mut u64,
    smallest_set: &mut bool,
    log_handle: &mut Option<fs::File>,
    root_device: Option<u64>,
    is_root: bool,
) -> (u64, bool, u32) {
    // First, lstat
    let md_symlink = match fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(_) => {
            // Should not happen for already-checked paths, but for children that disappeared? Return 0, no stats? Or treat as 0 with no entry?
            return (0, true, 0);
        }
    };
    if md_symlink.file_type().is_symlink() {
        // Should not happen for children (we filtered symlinks), but for direct inputs that are symlink-to-file, we handle here.
        // For symlink-to-dir direct inputs, this function is called with path being symlink-to-dir. But we classified it as dir, and now we need to treat as dir (follow).
        // How to distinguish? Check follow metadata.
        match fs::metadata(path) {
            Ok(target_md) => {
                if target_md.is_dir() {
                    // Treat as dir: need to traverse target (follow symlink). For reading dir, use path (which follows? read_dir on symlink-to-dir works). For size, use target's size/blocks? Or symlink's? For apparent, dir size? For symlink-to-dir as aggregated input (multiple mode), what is size? Earlier linkdir+sub as multiple gave both 4K (disk) - linkdir's size equals sub's size (target's subtree, not symlink itself). For apparent, linkdir vs sub? We didn't test apparent for linkdir multiple. Let's assume for symlink-to-dir, size is target's subtree (including target dir's own size, not symlink's). And stats include target's entries, not symlink itself? Need to verify.
                    // For now, treat as dir with target's metadata for own size, and traverse via path (which follows).
                    return aggregate_dir(path, &target_md, apparent, count_hard, stay_on_fs, ignore_set, seen_files, seen_dirs, entries_traversed, smallest, largest, smallest_set, log_handle, root_device, is_root);
                } else {
                    // symlink to file/other: treat as file with symlink's own metadata (md_symlink), not target's.
                    return aggregate_file(&md_symlink, path, apparent, count_hard, seen_files, entries_traversed, smallest, largest, smallest_set);
                }
            }
            Err(_) => {
                // broken - should have been classified as error before, but if called, return error? For direct broken, we already handled as error without calling this. For children, symlinks filtered, so not reached. Return 0.
                return (0, true, 0);
            }
        }
    } else if md_symlink.is_dir() {
        return aggregate_dir(path, &md_symlink, apparent, count_hard, stay_on_fs, ignore_set, seen_files, seen_dirs, entries_traversed, smallest, largest, smallest_set, log_handle, root_device, is_root);
    } else {
        // file, fifo, socket, etc.
        // For display, is_dir_like = !is_file (i.e., true for fifo etc., false for regular file and symlink-to-file? But here it's not symlink, so for regular file false, for other true. We'll return that.
        let is_file = md_symlink.is_file();
        let (size, _, _) = aggregate_file(&md_symlink, path, apparent, count_hard, seen_files, entries_traversed, smallest, largest, smallest_set);
        return (size, !is_file, 0);
    }
}

fn aggregate_file(
    md: &fs::Metadata,
    path: &Path,
    apparent: bool,
    count_hard: bool,
    seen_files: &mut HashMap<(u64,u64), HashSet<String>>,
    entries_traversed: &mut u64,
    smallest: &mut u64,
    largest: &mut u64,
    smallest_set: &mut bool,
) -> (u64, bool, u32) {
    let dev = md.dev();
    let ino = md.ino();
    let key = (dev, ino);
    let actual_size = if apparent { md.size() } else { md.blocks() * 512 };
    // nlink>1 indicates possible hardlink? But even nlink==1 could be hardlink? No, nlink==1 means single link, no dedup needed. But to be safe, check seen anyway (for duplicate same file? nlink==1 but same path twice would have same inode, nlink==1, but we still need to handle same-path-not-dedup vs different-path-dedup? For nlink==1, same inode different paths shouldn't happen (since nlink==1 means only one directory entry, so different paths with same inode impossible unless one is stale? Actually for nlink==1, different paths same inode impossible (except via bind mounts? Same file via different mount paths? Could be same inode different canonical paths via bind? Rare. We'll still check seen for correctness, but optimization: if nlink==1 and not already seen, just count and don't store? But for duplicate same path (f f), nlink==1, same inode, same canonical, we need to NOT dedup (count twice). If we store first, second would be seen, then we'd check canonical same => count again (correct). So need to store even for nlink==1 to handle duplicates? Actually for nlink==1, same inode same canonical (duplicate same file) should count twice, which our logic does (same canonical => count). If we didn't store, second would also count (correct as well, but without storing). So both work. For nlink==1, different canonical same inode shouldn't happen, so no dedup anyway. So we can skip tracking for nlink==1 to save canonicalize cost, but need to handle duplicates? Duplicates with nlink==1 would both count anyway (whether tracked or not). So we can skip tracking for nlink==1.
    // However, for stats smallest/largest, need to count entries. Good.
    // Let's implement: if md.nlink() == 1 and !seen_files.contains_key(&key) => fast path: count, update stats, don't store? But then second duplicate same file (nlink==1) would also fast path (since not stored), count again. Correct. Good.
    // But what about hardlinked files with nlink>1? Need tracking.
    // Simpler: always track, but canonicalize only when needed (when key already seen or nlink>1).
    if count_hard {
        // No dedup, always count
        *entries_traversed += 1;
        update_min_max(actual_size, smallest, largest, smallest_set);
        return (actual_size, false, 0);
    }
    // Check nlink
    if md.nlink() == 1 {
        // Could still be duplicate same path (nlink==1, same inode)? For duplicate same file (f f), nlink==1, same inode, same canonical. Our fast path would count twice (correct). For hardlink case with nlink>1, we need tracking. Since nlink==1, no hardlink dedup needed (except same-path duplicates which we want to count twice anyway). So just count.
        // But what about same inode via different paths with nlink==1? Impossible (nlink would be >=2). So safe.
        *entries_traversed += 1;
        update_min_max(actual_size, smallest, largest, smallest_set);
        return (actual_size, false, 0);
    }
    // nlink > 1: need dedup logic with canonical paths
    // Try to get canonical path
    let canon = fs::canonicalize(path).map(|p| p.to_string_lossy().to_string()).unwrap_or_else(|_| {
        // Fallback: absolute path? Use path as string? For relative, join with current_dir?
        // For simplicity, use path's string as is (may cause incorrect dedup for f vs ./f with nlink>1? But nlink>1 hardlinked files with same canonical via different strings (f vs ./f for hardlinked? No, f vs ./f same file, nlink may be >1 if hardlinked elsewhere? Example: f1 hardlinked to f2 (nlink=2), then f1 vs ./f1 (same file, same canonical, nlink=2). Our fallback using string would treat "f1" vs "./f1" as different, causing dedup (wrong, should count twice). But canonicalize should succeed for existing files, so fallback rarely used. Good.
        path.to_string_lossy().to_string()
    });
    if let Some(set) = seen_files.get_mut(&key) {
        if set.contains(&canon) {
            // Same file, count again
            *entries_traversed += 1;
            update_min_max(actual_size, smallest, largest, smallest_set);
            return (actual_size, false, 0);
        } else {
            // Different file, same inode => dedup to 0
            set.insert(canon);
            *entries_traversed += 1;
            update_min_max(0, smallest, largest, smallest_set);
            return (0, false, 0);
        }
    } else {
        let mut set = HashSet::new();
        set.insert(canon);
        seen_files.insert(key, set);
        *entries_traversed += 1;
        update_min_max(actual_size, smallest, largest, smallest_set);
        return (actual_size, false, 0);
    }
}

fn update_min_max(size: u64, smallest: &mut u64, largest: &mut u64, smallest_set: &mut bool) {
    if !*smallest_set {
        *smallest = size;
        *largest = size;
        *smallest_set = true;
    } else {
        if size < *smallest { *smallest = size; }
        if size > *largest { *largest = size; }
    }
}

