            info2.path = abs_path;
            // For is_dir, ensure correct (compute_entry_info determines is_dir via lstat, should match)
            entries.push(info2);
        }
    } else {
        // Single dir / CWD: entries are children of current_path
        let read = match fs::read_dir(current_path) {
            Ok(rd) => rd,
            Err(_) => return (vec![], 0, 0),
        };
        let mut children: Vec<PathBuf> = Vec::new();
        for ent in read {
            if let Ok(e) = ent {
                let p = e.path();
                if let Ok(md) = fs::symlink_metadata(&p) {
                    if md.file_type().is_symlink() {
                        continue;
                    }
                    children.push(p);
                }
            }
        }
        children.sort_by(|a,b| a.file_name().cmp(&b.file_name()));
        let root_dev = fs::metadata(current_path).map(|m| m.dev()).ok();
        for child in &children {
            let display = child.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or(child.to_string_lossy().to_string());
            // For child, is_root=false (so ignore applies)
            let info = compute_entry_info(child, display, None, apparent, count_hard, stay_on_fs, ignore_set, &mut seen_files, &mut seen_dirs, root_dev, false);
            entries.push(info);
        }
    }
    let total_desc: u64 = entries.iter().map(|e| e.count).sum();
    let _total_size: u64 = entries.iter().map(|e| e.size).sum();
    (entries, total_desc, _total_size)
}

