fn glob_match(pattern: &str, text: &str, case_insensitive: bool) -> bool {
    // Simple glob: support *, ?, [], **? For now support * and ? and exact.
    // Use glob crate? For simplicity, implement * and ?.
    let pat = if case_insensitive { pattern.to_lowercase() } else { pattern.to_string() };
    let txt = if case_insensitive { text.to_lowercase() } else { text.to_string() };
    // Convert glob to regex-like matching via recursion
    fn matches(p: &[char], t: &[char]) -> bool {
        if p.is_empty() { return t.is_empty(); }
        if p[0] == '*' {
            // * matches any sequence (including empty)
            // Try all splits
            for i in 0..=t.len() {
                if matches(&p[1..], &t[i..]) { return true; }
            }
            return false;
        } else if p[0] == '?' {
            if t.is_empty() { return false; }
            return matches(&p[1..], &t[1..]);
        } else if p[0] == '[' {
            // character class: find ]
            if let Some(end) = p.iter().position(|&c| c == ']') {
                if t.is_empty() { return false; }
                let class: Vec<char> = p[1..end].to_vec();
                let mut matched = false;
                let mut i = 0;
                while i < class.len() {
                    if i+2 < class.len() && class[i+1] == '-' {
                        let start = class[i];
                        let endc = class[i+2];
                        if t[0] >= start && t[0] <= endc { matched = true; break; }
                        i += 3;
                    } else {
                        if class[i] == t[0] { matched = true; break; }
                        i += 1;
                    }
                }
                // Handle negation [!...] or [^...]?
                // For simplicity, if first char is ! or ^, negate
                if !class.is_empty() && (class[0] == '!' || class[0] == '^') {
                    // Re-evaluate without !/^
                    let inner = &class[1..];
                    let mut inner_match = false;
                    let mut j = 0;
                    while j < inner.len() {
                        if j+2 < inner.len() && inner[j+1] == '-' {
                            if t[0] >= inner[j] && t[0] <= inner[j+2] { inner_match = true; break; }
                            j += 3;
                        } else {
                            if inner[j] == t[0] { inner_match = true; break; }
                            j += 1;
                        }
                    }
                    matched = !inner_match;
                }
                if !matched { return false; }
                return matches(&p[end+1..], &t[1..]);
            } else {
                // No closing ], treat [ as literal
                if t.is_empty() || t[0] != '[' { return false; }
                return matches(&p[1..], &t[1..]);
            }
        } else {
            if t.is_empty() || p[0] != t[0] { return false; }
            return matches(&p[1..], &t[1..]);
        }
    }
