fn format_size_nopad(bytes: u64, format: Format) -> String {
    // Same as format_size but without leading padding (trim leading spaces)
    let s = format_size(bytes, format);
    s.trim_start().to_string()
}

fn sort_entries(entries: &mut Vec<EntryInfo>, mode: SortMode) {
    match mode {
        SortMode::SizeDesc => entries.sort_by(|a,b| b.size.cmp(&a.size).then_with(|| b.display.cmp(&a.display))),
        SortMode::SizeAsc => entries.sort_by(|a,b| a.size.cmp(&b.size).then_with(|| b.display.cmp(&a.display))), // secondary name desc to match observed (stay c,b,a)
        SortMode::MtimeDesc => entries.sort_by(|a,b| b.mtime.cmp(&a.mtime).then_with(|| b.display.cmp(&a.display))),
        SortMode::MtimeAsc => entries.sort_by(|a,b| a.mtime.cmp(&b.mtime).then_with(|| a.display.cmp(&b.display))),
        SortMode::CountDesc => entries.sort_by(|a,b| b.count.cmp(&a.count).then_with(|| b.display.cmp(&a.display))),
        SortMode::CountAsc => entries.sort_by(|a,b| a.count.cmp(&b.count).then_with(|| a.display.cmp(&b.display))),
        SortMode::NameAsc => entries.sort_by(|a,b| a.display.cmp(&b.display)),
        SortMode::NameDesc => entries.sort_by(|a,b| b.display.cmp(&a.display)),
    }
}

// Compute size/count/mtime for a path (file or dir) with traversal, similar to aggregate but also return count and mtime
// For dirs, size = aggregated, count = total entries in subtree including self, mtime = dir's own mtime
// For files, size = file size (with hardlink dedup? For interactive, use global seen? For simplicity, use fresh per call? But for current view with multiple entries, need shared seen for dedup within view (like aggregate). So this function should take &mut seen sets shared across entries in same view.
// We'll implement a helper that given a list of paths (children or inputs), computes each entry's info with shared seen.

fn compute_entry_info(
    path: &Path,
    display: String,
    is_dir_hint: Option<bool>,
    apparent: bool,
    count_hard: bool,
    stay_on_fs: bool,
    ignore_set: &HashSet<String>,
    seen_files: &mut HashMap<(u64,u64), HashSet<String>>,
    seen_dirs: &mut HashSet<(u64,u64)>,
    root_device: Option<u64>,
    is_root: bool,
) -> EntryInfo {
    // lstat
    let md_symlink = fs::symlink_metadata(path).unwrap(); // caller ensures exists and not symlink (for children) or handles symlink for inputs? For inputs that are symlink-to-dir, path is symlink, need to follow. For children, no symlinks. So for children, md is not symlink. For inputs that are symlink-to-dir, we need to handle. To simplify, caller should resolve symlink-to-dir inputs to target path? Or pass path as symlink and handle here.
    // Handle symlink-to-dir: if symlink and target is dir, treat as dir with target metadata
    let (is_dir, md_for_self, traversal_path) = if md_symlink.file_type().is_symlink() {
        let target_md = fs::metadata(path).unwrap();
        if target_md.is_dir() {
            (true, target_md, path.to_path_buf()) // traversal via symlink path (read_dir follows)
        } else {
            // symlink to file: treat as file with symlink metadata
            (false, md_symlink, path.to_path_buf())
        }
    } else {
        (md_symlink.is_dir(), md_symlink, path.to_path_buf())
    };
    // Override with hint? For inputs, is_dir_hint from classification? Use computed is_dir.
    let _ = is_dir_hint;
    if is_dir {
        let (size, count) = compute_dir_size_count(&traversal_path, &md_for_self, apparent, count_hard, stay_on_fs, ignore_set, seen_files, seen_dirs, root_device, is_root);
        let mtime = md_for_self.modified().unwrap_or(std::time::UNIX_EPOCH);
        EntryInfo { path: path.to_path_buf(), display, is_dir: true, size, mtime, count }
    } else {
        // file
        let dev = md_for_self.dev();
        let ino = md_for_self.ino();
        let actual_size = if apparent { md_for_self.size() } else { md_for_self.blocks() * 512 };
        let mut size = actual_size;
        // hardlink dedup (similar to aggregate_file but simplified: only check if nlink>1 and !count_hard)
        if !count_hard && md_for_self.nlink() > 1 {
            let key = (dev, ino);
            let canon = fs::canonicalize(path).map(|p| p.to_string_lossy().to_string()).unwrap_or(path.to_string_lossy().to_string());
            if let Some(set) = seen_files.get_mut(&key) {
                if set.contains(&canon) {
                    // same file, count
                } else {
                    set.insert(canon);
                    size = 0;
                }
            } else {
                let mut set = HashSet::new();
                set.insert(canon);
                seen_files.insert(key, set);
            }
        }
        let mtime = md_for_self.modified().unwrap_or(std::time::UNIX_EPOCH);
        // count for file =1 (for parent aggregation, but display empty, sorting uses 1? We'll use 1)
        EntryInfo { path: path.to_path_buf(), display, is_dir: false, size, mtime, count: 1 }
    }
}

fn compute_dir_size_count(
    path: &Path,
    md: &fs::Metadata,
    apparent: bool,
    count_hard: bool,
    stay_on_fs: bool,
    ignore_set: &HashSet<String>,
    seen_files: &mut HashMap<(u64,u64), HashSet<String>>,
    seen_dirs: &mut HashSet<(u64,u64)>,
    root_device: Option<u64>,
    is_root: bool,
) -> (u64, u64) {
    // Check ignore/stay
    let mut skip_children = false;
    if !is_root {
        if stay_on_fs {
            if let Some(rd) = root_device {
                if md.dev() != rd {
                    skip_children = true;
                }
            }
        }
        if !skip_children {
            if let Ok(canon) = fs::canonicalize(path) {
                if ignore_set.contains(&canon.to_string_lossy().to_string()) {
                    skip_children = true;
                }
            }
        }
    }
    // Dir own size with dedup
    let key = (md.dev(), md.ino());
    let actual_self = if apparent { md.size() } else { md.blocks() * 512 };
    let mut self_size = actual_self;
    let mut self_count = 1;
    if !count_hard {
        if seen_dirs.contains(&key) {
            self_size = 0;
            // count? For second d (same dir), count? Earlier d d second dir's count? For title total, second d's count? For d d (same dir twice) as multiple inputs, each entry's count? First d count 2 (dir+file), second d count? Dir deduped (0 size) but file counted (50)? Count for second d? Dir itself counted as 1? Or 0? For title total (sum of counts), total descendants for d d? Earlier stats for d d showed entries_traversed 4 (dir, file, dir, file =4). That's sum of counts? First d count 2, second d count 2 (dir+file, even though dir size 0, still counted as entry). Yes. So for deduped dir, count still 1 for self (entries_traversed includes it). Good. So self_count always 1, regardless of dedup. Good.
        } else {
            seen_dirs.insert(key);
        }
    }
    if skip_children {
        return (self_size, self_count);
    }
    // Traverse children
    let read = match fs::read_dir(path) {
        Ok(rd) => rd,
        Err(_) => return (self_size, self_count),
    };
    let mut children: Vec<PathBuf> = Vec::new();
    for ent in read {
        if let Ok(e) = ent {
            let p = e.path();
            if let Ok(md_child) = fs::symlink_metadata(&p) {
                if md_child.file_type().is_symlink() {
                    continue;
                }
                if stay_on_fs {
                    if let Some(rd) = root_device.or(Some(md.dev())) {
                        if md_child.dev() != rd {
                            continue;
                        }
                    }
                }
                children.push(p);
            }
        }
    }
    children.sort_by(|a,b| a.file_name().cmp(&b.file_name()));
    let child_root = root_device.or(Some(md.dev()));
    let mut total_size = self_size;
    let mut total_count = self_count;
    for child in &children {
        // Recurse: need to handle file vs dir
        if let Ok(md_child) = fs::symlink_metadata(child) {
            if md_child.is_dir() {
                let (sz, cnt) = compute_dir_size_count(child, &md_child, apparent, count_hard, stay_on_fs, ignore_set, seen_files, seen_dirs, child_root, false);
                total_size += sz;
                total_count += cnt;
            } else {
                // file
                let actual = if apparent { md_child.size() } else { md_child.blocks() * 512 };
                let mut sz = actual;
                if !count_hard && md_child.nlink() > 1 {
                    let k = (md_child.dev(), md_child.ino());
                    let canon = fs::canonicalize(child).map(|p| p.to_string_lossy().to_string()).unwrap_or(child.to_string_lossy().to_string());
                    if let Some(set) = seen_files.get_mut(&k) {
                        if set.contains(&canon) {
                        } else {
                            set.insert(canon);
                            sz = 0;
                        }
                    } else {
                        let mut set = HashSet::new();
                        set.insert(canon);
                        seen_files.insert(k, set);
                    }
                }
                total_size += sz;
                total_count += 1;
            }
        }
    }
    (total_size, total_count)
}

fn load_entries(
    current_path: &Path,
    is_multi: bool,
    inputs: &Vec<String>,
    apparent: bool,
    count_hard: bool,
    stay_on_fs: bool,
    ignore_set: &HashSet<String>,
) -> (Vec<EntryInfo>, u64, u64) {
    // Returns (entries, total_descendants, total_size?) Actually total_descendants = sum of counts, total_size = sum of sizes. We'll compute.
    let mut seen_files: HashMap<(u64,u64), HashSet<String>> = HashMap::new();
    let mut seen_dirs: HashSet<(u64,u64)> = HashSet::new();
    let mut entries: Vec<EntryInfo> = Vec::new();
    if is_multi {
        // entries are inputs themselves
        for inp in inputs {
            let p = PathBuf::from(inp);
            // lstat to check existence and type
            let md_symlink = match fs::symlink_metadata(&p) {
                Ok(m) => m,
                Err(_) => {
                    // Error input in interactive? What does interactive show for nonexistent? Need to test. For now, skip? Or show with 0 size and error? Interactive probably skips errors? Or shows? Let's check: interactive with nonexistent input? Test later. For now, skip errors (don't include).
                    continue;
                }
            };
            let is_symlink = md_symlink.file_type().is_symlink();
            let (is_dir, display) = if is_symlink {
                match fs::metadata(&p) {
                    Ok(tm) => {
                        if tm.is_dir() {
                            (true, inp.clone())
                        } else {
                            (false, inp.clone())
                        }
                    }
                    Err(_) => continue, // broken, skip
                }
            } else {
                (md_symlink.is_dir(), inp.clone())
            };
            // For display, for interactive multi, display is as-given (inp.clone()). Good.
            // For path, need absolute for traversal? Use p as is (relative works with read_dir). For canonicalize for ignore/hardlink, need absolute? fs::canonicalize handles relative. Good. Keep p as is (could be relative). But for navigation (descending), need absolute? We'll store absolute via canonicalize or join with cwd? For relative inputs like "d1", when descending, current_path should become absolute "/tmp/.../d1" (as observed title shows absolute). Good. So for is_dir entries, path should be absolute (canonicalized) for navigation. For files, path can be as is? But for marking/deletion, need correct path (relative works if cwd unchanged? But if user navigates (cwd doesn't change, only view changes), relative paths still valid relative to original cwd? Since we never chdir, relative paths remain valid. Good. But to be safe, store absolute for all.
            let abs_path = fs::canonicalize(&p).unwrap_or(p.clone());
            // root_device for this input (for stay_on_fs): if dir, its device, else None? For files, no children, so None.
            let root_dev = if is_dir {
                fs::metadata(&p).map(|m| m.dev()).ok()
            } else {
                None
            };
            let info = compute_entry_info(&p, display, Some(is_dir), apparent, count_hard, stay_on_fs, ignore_set, &mut seen_files, &mut seen_dirs, root_dev, true);
            // Override path with abs for navigation? compute_entry_info already stored p (relative). For navigation, we need abs. Let's set path to abs.
            let mut info2 = info;
            info2.path = abs_path;
            // For is_dir, ensure correct (compute_entry_info determines is_dir via lstat, should match)
            entries.push(info2);
        }
    } else {
        // Single dir / CWD: entries are children of current_path
        let read = match fs::read_dir(current_path) {
            Ok(rd) => rd,
            Err(_) => return (vec![], 0, 0),
        };
        let mut children: Vec<PathBuf> = Vec::new();
        for ent in read {
            if let Ok(e) = ent {
                let p = e.path();
                if let Ok(md) = fs::symlink_metadata(&p) {
                    if md.file_type().is_symlink() {
                        continue;
                    }
                    children.push(p);
                }
            }
        }
        children.sort_by(|a,b| a.file_name().cmp(&b.file_name()));
        let root_dev = fs::metadata(current_path).map(|m| m.dev()).ok();
        for child in &children {
            let display = child.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or(child.to_string_lossy().to_string());
            // For child, is_root=false (so ignore applies)
            let info = compute_entry_info(child, display, None, apparent, count_hard, stay_on_fs, ignore_set, &mut seen_files, &mut seen_dirs, root_dev, false);
            entries.push(info);
        }
    }
    let total_desc: u64 = entries.iter().map(|e| e.count).sum();
    let _total_size: u64 = entries.iter().map(|e| e.size).sum();
    (entries, total_desc, _total_size)
}

pub fn run(
    input: Vec<String>,
    format: Format,
    apparent: bool,
    count_hard: bool,
    stay_on_fs: bool,
    _ignore_raw: Vec<String>,
    canonicalized_ignore: Vec<String>,
    _log: Option<fs::File>,
) {
    use crossterm::{terminal::{enable_raw_mode, disable_raw_mode, size, EnterAlternateScreen, LeaveAlternateScreen}, execute, cursor::{Hide, Show}, event::{read, Event, KeyCode, KeyModifiers}};
    use std::io::{stdout, Write};

    let ignore_set: HashSet<String> = canonicalized_ignore.into_iter().collect();
    let cwd_abs = fs::canonicalize(".").unwrap_or(PathBuf::from("."));

    let (mut current_path, mut is_multi_view, mut initial_inputs) = if input.is_empty() {
        (cwd_abs.clone(), false, vec![])
    } else if input.len() == 1 {
        let p = PathBuf::from(&input[0]);
        let is_dir = match fs::symlink_metadata(&p) {
            Ok(md) => {
                if md.file_type().is_symlink() {
                    fs::metadata(&p).map(|m| m.is_dir()).unwrap_or(false)
                } else {
                    md.is_dir()
                }
            }
            Err(_) => false,
        };
        if is_dir {
            let canon = fs::canonicalize(&p).unwrap_or(p.clone());
            (canon, false, vec![])
        } else {
            (cwd_abs.clone(), true, input.clone())
        }
    } else {
        (cwd_abs.clone(), true, input.clone())
    };

    let mut sort_mode = SortMode::SizeDesc;
    let mut show_mtime = false;
    let mut show_count = false;
    let mut bar_mode = BarMode::PercentAndBar;
    let mut selected: usize = 0;
    let mut scroll_offset: usize = 0;
    let mut marked: HashSet<PathBuf> = HashSet::new();
    let mut show_help = false;
    let mut show_marked_pane = false;
    let mut active_pane: usize = 0;
    let mut marked_selected: usize = 0;
    let mut search_active = false;
    let mut search_query = String::new();
    let mut search_case_insensitive = true;
    let mut search_filter: Option<String> = None;

    let mut history: Vec<(PathBuf, bool, Vec<String>)> = Vec::new();

    let start_time = std::time::Instant::now();
    let (mut entries_unfiltered, mut _total_desc, _) = load_entries(&current_path, is_multi_view, &initial_inputs, apparent, count_hard, stay_on_fs, &ignore_set);
    sort_entries(&mut entries_unfiltered, sort_mode);
    let mut global_total_size: u64 = entries_unfiltered.iter().map(|e| e.size).sum();
    let mut global_entries_count: u64 = entries_unfiltered.iter().map(|e| e.count).sum();

    enable_raw_mode().unwrap();
    let mut out = stdout();
    execute!(out, EnterAlternateScreen, Hide).unwrap();

    let result = (|| -> Result<(), std::io::Error> {
        loop {
            // Apply filter
            let visible_entries: Vec<EntryInfo> = if let Some(ref filt) = search_filter {
                if filt.is_empty() {
                    entries_unfiltered.clone()
                } else {
                    entries_unfiltered.iter().filter(|e| glob_match(filt, &e.display, search_case_insensitive)).cloned().collect()
                }
